import axios from 'axios';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

// Tasks API
export const tasksAPI = {
  getAll: (params) => axios.get('/api/tasks', { params }),
  create: (data) => axios.post('/api/tasks', data),
  update: (id, data) => axios.put(`/api/tasks/${id}`, data),
  delete: (id) => axios.delete(`/api/tasks/${id}`),
  getStats: () => axios.get('/api/tasks/stats')
};

// Goals API
export const goalsAPI = {
  getAll: () => axios.get('/api/goals'),
  create: (data) => axios.post('/api/goals', data),
  update: (id, data) => axios.put(`/api/goals/${id}`, data),
  delete: (id) => axios.delete(`/api/goals/${id}`)
};

// Diary API
export const diaryAPI = {
  getAll: (params) => axios.get('/api/diary', { params }),
  create: (data) => axios.post('/api/diary', data),
  update: (id, data) => axios.put(`/api/diary/${id}`, data),
  delete: (id) => axios.delete(`/api/diary/${id}`)
};

// Users API
export const usersAPI = {
  updateProfile: (data) => axios.put('/api/users/profile', data),
  updatePreferences: (data) => axios.put('/api/users/preferences', data)
};
